    'wine_answers', $q$select coalesce(jsonb_agg(jsonb_build_object('wine_id', wine_id, 'region_id', region_id, 'appellation_id', appellation_id) order by wine_id), '[]'::jsonb) as refs from wine_answers where region_id = any ($1) or appellation_id = any ($2)$q$,
    'guesses', $q$select coalesce(jsonb_agg(jsonb_build_object('id', id, 'region_id', region_id, 'appellation_id', appellation_id, 'total_points', total_points) order by id), '[]'::jsonb) as refs from guesses where region_id = any ($1) or appellation_id = any ($2)$q$,
    'wine_archetypes', $q$select coalesce(jsonb_agg(jsonb_build_object('id', id, 'region_id', region_id, 'appellation_id', appellation_id) order by id), '[]'::jsonb) as refs from wine_archetypes where region_id = any ($1) or appellation_id = any ($2)$q$,
    'label_lookups', $q$select coalesce(jsonb_agg(jsonb_build_object('id', id, 'region_id', region_id, 'appellation_id', appellation_id) order by id), '[]'::jsonb) as refs from label_lookups where region_id = any ($1) or appellation_id = any ($2)$q$,
    'profile_favourite_regions', $q$select coalesce(jsonb_agg(jsonb_build_object('profile_id', profile_id, 'region_id', region_id) order by profile_id, region_id), '[]'::jsonb) as refs from profile_favourite_regions where region_id = any ($1) and $2::uuid[] is not null$q$,
    'training_attempts', $q$select coalesce(jsonb_agg(jsonb_build_object('id', id, 'picked_region_id', picked_region_id) order by id), '[]'::jsonb) as refs from training_attempts where picked_region_id = any ($1) and $2::uuid[] is not null$q$,
    'type_designations', $q$select coalesce(jsonb_agg(jsonb_build_object('id', id, 'region_id', region_id) order by id), '[]'::jsonb) as refs from type_designations where region_id = any ($1) and $2::uuid[] is not null$q$,
    'wine_identity_drafts', $q$select coalesce(jsonb_agg(jsonb_build_object('wine_id', wine_id, 'region_id', draft ->> 'regionId', 'appellation_id', draft ->> 'appellationId') order by wine_id), '[]'::jsonb) as refs from wine_identity_drafts where draft ->> 'regionId' = any ($1::text[]) or draft ->> 'appellationId' = any ($2::text[])$q$
