  v_live boolean;
  v_us uuid;
  v_regions uuid[];
  v_apps uuid[];
  v_x jsonb;
  v_p jsonb;
  v_got jsonb;
  v_n int;
  v_m int;
  v_i int;
  v_id uuid;
  v_to uuid;
  v_loser uuid;
  v_kept uuid;
  v_kept_region uuid;
  v_region uuid;
  v_into uuid;
begin
  select id into v_us from countries where name = 'United States';
